"use client";

import { useEffect, useState, useMemo } from "react";
import { getGlobalSlot, getPageSlot } from "../lib/time";

export function useLiveProductMetric(staticNumber: number) {
  const [tick, setTick] = useState(Date.now());

  useEffect(() => {
    const update = () => setTick(Date.now());

    const now = Date.now();
    const nextSlot = 5000 - (now % 5000); // milliseconds until next 5s slot
    const timeout = setTimeout(() => {
      update();

      const interval = setInterval(update, 5000); // every 5s after first slot
      return () => clearInterval(interval);
    }, nextSlot);

    return () => clearTimeout(timeout);
  }, []);

  return useMemo(() => {
    // calculate deterministic globalNumber and pageDelta
    const globalSlot = getGlobalSlot(tick);
    const globalNumber = (globalSlot % 90) + 60; // 60–149

    const pageSlot = getPageSlot(tick);
    const pageDelta = (pageSlot % 21) - 10; // -10 → +10

    return staticNumber * globalNumber + pageDelta;
  }, [tick, staticNumber]);
}
